/**
 * Elige el adaptador del estado compartido en caliente (ADR-THYROX-006, 1.1.0).
 *
 * Con `THYROX_REDIS_URL` abre el adaptador Redis; sin ella, el de memoria, que
 * sólo vale para un proxy. Si Redis falla a mitad de operación, esa llamada se
 * atiende en memoria con un aviso, y la siguiente vuelve a intentar Redis: una
 * caída breve no deja al proxy con la vista local hasta reiniciarlo. El aviso
 * sale al entrar en degradación, no en cada llamada mientras dura. Lo que exige
 * vista global en modo multi-proxy rehúsa en su propio consumidor, no aquí.
 */
import { createMemorySharedStateStore } from './memory.ts'
import type { SharedStateStore } from './port.ts'
import { createRedisSharedStateStore } from './redis.ts'

export const REDIS_URL_ENV = 'THYROX_REDIS_URL'

export type SharedStateBackend = 'memory' | 'redis'

export interface OpenSharedStateOptions {
  env?: Record<string, string | undefined>
  createMemory?: () => SharedStateStore
  createRedis?: (url: string) => SharedStateStore
  warn?: (message: string) => void
}

export interface OpenedSharedState {
  store: SharedStateStore
  backend: SharedStateBackend
  degraded: () => boolean
}

export function openSharedStateStore(options: OpenSharedStateOptions = {}): OpenedSharedState {
  const env = options.env ?? process.env
  const createMemory = options.createMemory ?? (() => createMemorySharedStateStore())
  const url = env[REDIS_URL_ENV]?.trim()
  if (!url) {
    return { store: createMemory(), backend: 'memory', degraded: () => false }
  }
  const createRedis = options.createRedis ?? ((redisUrl: string) => createRedisSharedStateStore(redisUrl))
  const warn = options.warn ?? ((message: string) => console.warn(message))
  const redis = createRedis(url)
  let fallback: SharedStateStore | null = null
  let degraded = false

  // Cada operación intenta redis primero; si falla, la atiende memoria.
  async function call<T>(operation: (store: SharedStateStore) => Promise<T>): Promise<T> {
    try {
      const result = await operation(redis)
      degraded = false
      return result
    } catch (error) {
      if (!degraded) {
        warn(
          `${REDIS_URL_ENV}: redis falló (${error instanceof Error ? error.message : String(error)}); ` +
            'el estado compartido degrada a memoria local de este proxy hasta que redis responda',
        )
      }
      degraded = true
      fallback ??= createMemory()
      return operation(fallback)
    }
  }

  const store: SharedStateStore = {
    incrementWindow: (key, windowMs, by) => call(s => s.incrementWindow(key, windowMs, by)),
    acquireLease: (key, owner, ttlMs) => call(s => s.acquireLease(key, owner, ttlMs)),
    releaseLease: (key, owner) => call(s => s.releaseLease(key, owner)),
    getWithTtl: key => call(s => s.getWithTtl(key)),
    setWithTtl: (key, value, ttlMs) => call(s => s.setWithTtl(key, value, ttlMs)),
    close: async () => {
      await redis.close().catch(() => {})
      if (fallback) await fallback.close()
    },
  }
  return { store, backend: 'redis', degraded: () => degraded }
}
=== memory.ts ===
/**
 * Adaptador `memory` de `SharedStateStore`: coordina dentro de un solo
 * proceso, con el reloj de pared por defecto (`options.now` lo sustituye
 * para pruebas deterministas). No abre sockets ni temporizadores: la
 * caducidad de un lease o un valor se resuelve al leerlo (perezosa), así
 * que nada mantiene el proceso vivo.
 */
import type { SharedStateStore } from './port.ts'

interface WindowEntry {
  windowIndex: number
  count: number
}

interface LeaseEntry {
  owner: string
  expiresAt: number
}

interface ValueEntry {
  value: string
  expiresAt: number
}

export interface MemorySharedStateStoreOptions {
  now?: () => number
}

/**
 * Un lease o un valor caduca en el instante `expiresAt`: en ese instante ya
 * está libre, no un tick después. `>=` (no `>`) es la frontera que hace que
 * el borde exacto cuente como caducado.
 */
function hasExpired(expiresAt: number, now: number): boolean {
  return now >= expiresAt
}

export function createMemorySharedStateStore(options: MemorySharedStateStoreOptions = {}): SharedStateStore {
  const now = options.now ?? Date.now
  const windows = new Map<string, WindowEntry>()
  const leases = new Map<string, LeaseEntry>()
  const values = new Map<string, ValueEntry>()

  return {
    async incrementWindow(key, windowMs, by = 1) {
      if (by <= 0) {
        throw new Error(`incrementWindow: "by" tiene que ser positivo, llegó ${by}`)
      }
      const windowIndex = Math.floor(now() / windowMs)
      const existing = windows.get(key)
      const count = existing !== undefined && existing.windowIndex === windowIndex ? existing.count + by : by
      windows.set(key, { windowIndex, count })
      return count
    },

    async acquireLease(key, owner, ttlMs) {
      const current = now()
      const existing = leases.get(key)
      if (existing !== undefined && !hasExpired(existing.expiresAt, current) && existing.owner !== owner) {
        return false
      }
      leases.set(key, { owner, expiresAt: current + ttlMs })
      return true
    },

    async releaseLease(key, owner) {
      const current = now()
      const existing = leases.get(key)
      if (existing === undefined || hasExpired(existing.expiresAt, current)) {
        return false
      }
      if (existing.owner !== owner) {
        return false
      }
      leases.delete(key)
      return true
    },

    async getWithTtl(key) {
      const current = now()
      const existing = values.get(key)
      if (existing === undefined) {
        return null
      }
      if (hasExpired(existing.expiresAt, current)) {
        values.delete(key)
        return null
      }
      return existing.value
    },

    async setWithTtl(key, value, ttlMs) {
      values.set(key, { value, expiresAt: now() + ttlMs })
    },

    async close() {
      windows.clear()
      leases.clear()
      values.clear()
    },
  }
}
=== redis.ts ===
/**
 * Adaptador `redis` de `SharedStateStore` (`./port.ts`) sobre
 * `Bun.RedisClient`, el cliente nativo de Bun 1.3 — no `ioredis`.
 *
 * `acquireLease` y la renovación por el mismo dueño necesitan ser atómicas
 * frente a otro proceso compitiendo por la misma clave, así que van por un
 * script Lua (`EVAL`, vía `client.send`): comprueban el dueño actual y sólo
 * entonces escriben, sin que otro cliente pueda intercalarse entre las dos
 * órdenes. `releaseLease` es el mismo patrón, en sentido contrario.
 */
import type { SharedStateStore } from './port.ts'

/**
 * Renueva el lease si `ARGV[1]` ya es su dueño; si no, lo toma con `NX`
 * (falla si otro dueño lo tiene vivo). Devuelve 1 si `ARGV[1]` queda como
 * dueño, 0 si no.
 */
const ACQUIRE_OR_RENEW_LEASE_SCRIPT = `
if redis.call("GET", KEYS[1]) == ARGV[1] then
  redis.call("PEXPIRE", KEYS[1], ARGV[2])
  return 1
end
if redis.call("SET", KEYS[1], ARGV[1], "PX", ARGV[2], "NX") then
  return 1
end
return 0
`

/** Borra la clave sólo si su valor es `ARGV[1]`. Devuelve 1 si borró, 0 si no. */
const RELEASE_LEASE_SCRIPT = `
if redis.call("GET", KEYS[1]) == ARGV[1] then
  return redis.call("DEL", KEYS[1])
end
return 0
`

export interface RedisSharedStateStoreOptions {
  /** Se antepone a toda clave, para que varios consumidores compartan un servidor sin chocar. */
  keyPrefix?: string
}

export function createRedisSharedStateStore(
  url: string,
  options: RedisSharedStateStoreOptions = {},
): SharedStateStore {
  const keyPrefix = options.keyPrefix ?? ''
  const client = new Bun.RedisClient(url)

  function prefixedKey(key: string): string {
    return `${keyPrefix}${key}`
  }

  return {
    async incrementWindow(key, windowMs, by = 1) {
      const windowFloor = Math.floor(Date.now() / windowMs)
      const windowKey = `${prefixedKey(key)}:${windowFloor}`
      const total = await client.incrby(windowKey, by)
      // La ventana sólo puede volver a leerse dentro de `windowMs`: pasado
      // ese plazo la clave de ventana cambia sola por el `floor` de arriba.
      await client.pexpire(windowKey, windowMs)
      return total
    },

    async acquireLease(key, owner, ttlMs) {
      const acquired = await client.send('EVAL', [
        ACQUIRE_OR_RENEW_LEASE_SCRIPT,
        '1',
        prefixedKey(key),
        owner,
        String(ttlMs),
      ])
      return acquired === 1
    },

    async releaseLease(key, owner) {
      const released = await client.send('EVAL', [RELEASE_LEASE_SCRIPT, '1', prefixedKey(key), owner])
      return released === 1
    },

    async getWithTtl(key) {
      return client.get(prefixedKey(key))
    },

    async setWithTtl(key, value, ttlMs) {
      await client.set(prefixedKey(key), value, 'PX', String(ttlMs))
    },

    async close() {
      client.close()
    },
  }
}
=== contract.ts ===
/**
 * La suite de contrato de `SharedStateStore`: cada adaptador la ejecuta
 * desde su propia prueba con su fábrica. Mide la semántica que los
 * consumidores dan por supuesta, no la implementación: si `memory` y `redis`
 * la pasan los dos, un proxy puede cambiar de uno a otro sin cambiar de
 * conducta.
 *
 * Los plazos son cortos y reales: el adaptador `redis` usa el reloj del
 * servidor, así que no hay reloj inyectable común a los dos.
 */
import { afterEach, beforeEach, describe, expect, test } from 'bun:test'

import type { SharedStateStore } from './port.ts'

const SHORT_TTL_MS = 60
const PAST_SHORT_TTL_MS = 150

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

export function describeSharedStateStoreContract(label: string, create: () => Promise<SharedStateStore>): void {
  describe(`contrato de SharedStateStore: ${label}`, () => {
    let store: SharedStateStore
    let prefix: string

    beforeEach(async () => {
      store = await create()
      prefix = `contract:${crypto.randomUUID()}:`
    })

    afterEach(async () => {
      await store.close()
    })

    test('incrementWindow acumula dentro de la ventana y cuenta 1 por omisión', async () => {
      expect(await store.incrementWindow(`${prefix}w`, 10_000)).toBe(1)
      expect(await store.incrementWindow(`${prefix}w`, 10_000, 4)).toBe(5)
    })

    test('incrementWindow vuelve a cero en una ventana nueva', async () => {
      await store.incrementWindow(`${prefix}w`, SHORT_TTL_MS, 3)
      await sleep(PAST_SHORT_TTL_MS)
      expect(await store.incrementWindow(`${prefix}w`, SHORT_TTL_MS)).toBe(1)
    })

    test('las claves no se mezclan', async () => {
      await store.incrementWindow(`${prefix}a`, 10_000, 2)
      expect(await store.incrementWindow(`${prefix}b`, 10_000)).toBe(1)
    })

    test('un lease tomado no lo obtiene otro dueño', async () => {
      expect(await store.acquireLease(`${prefix}l`, 'p1', 10_000)).toBe(true)
      expect(await store.acquireLease(`${prefix}l`, 'p2', 10_000)).toBe(false)
    })

    test('el mismo dueño lo vuelve a obtener y lo renueva', async () => {
      expect(await store.acquireLease(`${prefix}l`, 'p1', SHORT_TTL_MS)).toBe(true)
      expect(await store.acquireLease(`${prefix}l`, 'p1', 10_000)).toBe(true)
      await sleep(PAST_SHORT_TTL_MS)
      expect(await store.acquireLease(`${prefix}l`, 'p2', 10_000)).toBe(false)
    })

    test('un lease caducado queda libre', async () => {
      await store.acquireLease(`${prefix}l`, 'p1', SHORT_TTL_MS)
      await sleep(PAST_SHORT_TTL_MS)
      expect(await store.acquireLease(`${prefix}l`, 'p2', 10_000)).toBe(true)
    })

    test('releaseLease sólo suelta el lease de su dueño', async () => {
      await store.acquireLease(`${prefix}l`, 'p1', 10_000)
      expect(await store.releaseLease(`${prefix}l`, 'p2')).toBe(false)
      expect(await store.acquireLease(`${prefix}l`, 'p2', 10_000)).toBe(false)
      expect(await store.releaseLease(`${prefix}l`, 'p1')).toBe(true)
      expect(await store.acquireLease(`${prefix}l`, 'p2', 10_000)).toBe(true)
    })

    test('releaseLease sobre un lease inexistente devuelve false', async () => {
      expect(await store.releaseLease(`${prefix}nadie`, 'p1')).toBe(false)
    })

    test('setWithTtl guarda y getWithTtl devuelve null al caducar', async () => {
      expect(await store.getWithTtl(`${prefix}v`)).toBeNull()
      await store.setWithTtl(`${prefix}v`, 'valor', SHORT_TTL_MS)
      expect(await store.getWithTtl(`${prefix}v`)).toBe('valor')
      await sleep(PAST_SHORT_TTL_MS)
      expect(await store.getWithTtl(`${prefix}v`)).toBeNull()
    })
  })
}

