    await opened.forConsistency('localAllowed').getWithTtl('k')
    await opened.close()
    await opened.close()
    expect(calls.filter(c => c === 'redis:close')).toHaveLength(1)
    expect(calls.filter(c => c === 'memory:close')).toHaveLength(2)
  })
})
